@pragma('vm:never-inline')
@pragma('vm:entry-point')
int fn0(List<List<int>> grid) {
  if (grid.isEmpty) return 0;

  var count = 0;
  for (var i = 0; i < grid.length; i++) {
    for (var j = 0; j < grid[i].length; j++) {
      if ((i + j) % 2 != 0 && grid[i][j] == 1) {
        count++;
      }
    }
  }
  return count;
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(List<String> recipes) {
  final result = <String>[];
  for (var r = 0; r < recipes.length; r++) {
    final s = recipes[r];
    var expanded = '';
    var balance = 0;
    var i = 0;
    while (i < s.length) {
      final ch = s[i];
      i++;
      final start = i;
      while (i < s.length) {
        final c = s.codeUnitAt(i);
        if (c < 48 || c > 57) break;
        i++;
      }
      int count;
      if (start == i) {
        count = 1;
      } else {
        count = int.parse(s.substring(start, i));
      }
      for (var k = 0; k < count; k++) {
        expanded = expanded + ch;
        if (ch == 'C') {
          balance = balance + 1;
        } else if (ch == 'D') {
          balance = balance - 1;
        }
      }
    }
    if (balance > 0) {
      result.add(expanded);
    }
  }
  return result;
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(List<double> entries, int window) {
  if (window <= 0) return 0.0;
  if (entries.length < window) return 0.0;

  double sum = 0.0;
  for (int i = 0; i < window; i++) {
    sum += entries[i];
  }

  double best = sum / window;
  for (int i = window; i < entries.length; i++) {
    sum += entries[i] - entries[i - window];
    final double avg = sum / window;
    if (avg > best) {
      best = avg;
    }
  }
  return best;
}
